REPLACE INTO `notification_templates` (`id`, `source_key`, `subject`, `body`, `threshold_days`, `is_active`, `version`, `active_source_key`) VALUES (1,'vehicul.itp','Expirare <eveniment> – <numar autovehicul> la data de <data expirare>','Atenție: <eveniment> pentru autovehiculul <numar autovehicul> (<descriere autovehicul>) expiră la data de <data expirare>, peste <zile ramase> zile. Vă rugăm să luați măsurile necesare înainte de această dată.',15,1,1,'vehicul.itp'),
(2,'vehicul.asigurare','Expirare <eveniment> – <numar autovehicul> la data <data expirare>','Atenție: <eveniment> pentru autovehiculul <numar autovehicul> (<descriere autovehicul>) expiră la data de <data expirare>, peste <zile ramase> zile. Vă rugăm să luați măsurile necesare înainte de această dată.',30,1,0,'vehicul.asigurare'),
(3,'vehicul.rovinieta','Expirare <eveniment> – <numar autovehicul> la data <data expirare>','Atenție: <eveniment> pentru autovehiculul <numar autovehicul> (<descriere autovehicul>) expiră la data de <data expirare>, peste <zile ramase> zile. Vă rugăm să luați măsurile necesare înainte de această dată.',30,1,0,'vehicul.rovinieta'),
(4,'mentenanta.scadenta','Scadență mentenanță – <beneficiar>, <punct de lucru>','Intervenția de mentenanță la punctul de lucru <punct de lucru> (<adresa punct de lucru>) al beneficiarului <beneficiar>, contract <numar contract>, este programată pentru <data expirare> (zile rămase: <zile ramase>; zile de depășire: <zile depasire>). Ultima intervenție de mentenanță: <data ultima interventie>.',30,1,0,'mentenanta.scadenta'),
(5,'contract.expirare','Expirare contract – <beneficiar>','Contractul de mentenanță <numar contract> al beneficiarului <beneficiar> expiră la data de <data expirare> (zile rămase: <zile ramase>; zile de depășire: <zile depasire>).',30,1,0,'contract.expirare'),
(6,'intrare.factura-asteptata','Factură așteptată – <furnizor>','De la furnizorul <furnizor> s-au primit produse la data de <data receptie> (<numar produse> produse) fără factură. Factura era așteptată până la <data expirare> (zile rămase: <zile ramase>; zile de depășire: <zile depasire>).',7,1,0,'intrare.factura-asteptata'),
(7,'stoc.iesiri-peste-stoc','Ieșiri peste stoc nerezolvate – <produs>','Produsul <produs> are stoc negativ după <numar iesiri> ieșiri peste stoc, prima din <data prima iesire> (cauza: <cauza>). Regularizarea era așteptată până la <data expirare> (zile rămase: <zile ramase>; zile de depășire: <zile depasire>).',7,1,0,'stoc.iesiri-peste-stoc'),
(8,'stoc.sub-minim','Stoc sub minim – <produs>','Produsul <produs> are stocul <stoc> buc., sub minimul de <stoc minim> buc. (lipsesc <lipsa pana la minim> buc. până la minim).',1,1,0,'stoc.sub-minim'),
(9,'stoc.rezervare-fara-miscare','Rezervare fără mișcare – <produs>','Proiectul <proiect> ține rezervate <cantitate rezervata> buc. din <produs> fără nicio mișcare de peste 30 de zile. Revizuirea era așteptată până la <data expirare> (zile de depășire: <zile depasire>).',1,1,0,'stoc.rezervare-fara-miscare'),
(10,'proiect.deficit-termen','Deficit la proiectul <proiect>','Proiectul <proiect> are termen la <termen proiect> și încă <numar repere de achizitionat> repere de achiziționat (vezi lista de achiziție din situația proiectului). Zile rămase: <zile ramase>; zile de depășire: <zile depasire>.',14,1,0,'proiect.deficit-termen'),
(11,'sistem.backup-lipsa','Backup lipsă – ultimul: <ultimul backup>','Nu s-a făcut niciun backup de peste <vechime maxima> zile. Ultimul backup: <ultimul backup>. Ultima eroare: <ultima eroare backup>. Verifică Setări → Backup NAS și programarea zilnică.',1,1,0,'sistem.backup-lipsa'),
(12,'sistem.copie-nas-lipsa','Copie pe NAS lipsă','Backup-ul nu a ajuns pe NAS. Ultima încercare: <ultima copiere>. Cauza: <cauza copiere>. Verifică Setări → Backup NAS: conexiunea, contul și spațiul de pe NAS.',1,1,0,'sistem.copie-nas-lipsa'),
(13,'sistem.ceas-server-decalat','Ceasul serverului este decalat','Ceasul serverului este <decalaj ceas> față de ora de pe internet (constatat: <constatat ceas>). Backup-urile iau ora de pe internet, iar ștergerea automată a pachetelor vechi este oprită până la corectare. Verifică data și ora serverului.',1,1,0,'sistem.ceas-server-decalat'),
(14,'analiza-risc.expirare','Expirare analiză de risc – <beneficiar>, <punct de lucru>','Analiza de risc nr. <numar inregistrare> a punctului de lucru <punct de lucru> (<adresa punct de lucru>) al beneficiarului <beneficiar>, întocmită de <intocmit de>, expiră la data de <data expirare> (ultima reînnoire: <data ultima reinnoire>; valabilitate: <valabilitate luni> luni; zile rămase: <zile ramase>; zile de depășire: <zile depasire>).',60,1,0,'analiza-risc.expirare');
REPLACE INTO `offer_lines` (`id`, `offer_id`, `line_order`, `section`, `number`, `product_type`, `name`, `name_key`, `unit`, `quantity`, `in_stock`, `product_id`) VALUES (1,1,1,'Echipamente','1','CENTRALA CONTROL ACCES','Datele de comunicare sunt criptate pentru a imbunatati siguranta sistemului. Interfata RS485 si Wiegand (W26/W34), compatibilitate cu cititoare terta parte. \nControlerul suporta operatiuni offline. Dispune de un tamper pentru siguranta sporita. Posibilitate de alimentare back-up cu acumulator.','dateledecomunicaresuntcriptatepentruaimbunatatisigurantasistemuluiinterfatars485siwiegandw26w34compatibilitatecucititoaretertapartecontrolerulsuportaoperatiuniofflinedispunedeuntamperpentrus','Buc',1.000,1,NULL),
(2,1,2,'Echipamente','2','CITITOARE CONTROL ACCES','Producator HIKVISION, Cartele suportate MIFARE 13.56MHz, Alimentare:12VDC ± 25%\nConsum max. 1.6W, Conectivitate Wiegand 26/34 protocol\nDistanta de citire max. 50mm, Timp citire max. 300 ms\nTemperatura de functionare:-20-65°C, IP65\nDimensiuni:87 × 87 × 13.3mm\nAlte caracteristici:Led si Beeper incorporate\nStandard Radiofrecventa:ISO 14443-A\nTastatura	12 butoane (0~9,*,#)','producatorhikvisioncartelesuportatemifare1356mhzalimentare12vdc25consummax16wconectivitatewiegand2634protocoldistantadecitiremax50mmtimpcitiremax300mstemperaturadefunctionare2065cip65dimensi','Buc',2.000,1,NULL),
(3,1,3,'Echipamente','3','ELECTROMAGNETI','Electromagnet de 280 Kgf cu monitorizare, bobina din CUPRU 100%, montare aparenta.','electromagnetde280kgfcumonitorizarebobinadincupru100montareaparenta','Buc',2.000,1,NULL),
(4,1,4,'Echipamente','4','ELECTROMAGNETI','Suport inoxidabil ZL pt. electromagnet\nSuport inoxidabil din duraluminiu pentru montarea electromagnetilor la usi cu deschidere in interior.\nElectromagnetul se monteaza deasupra usii, in interior, folosind suportul L. Contraplaca se monteaza pe usa, la nivelul electromagnetului, folosind suportul Z.','suportinoxidabilzlptelectromagnetsuportinoxidabildinduraluminiupentrumontareaelectromagnetilorlausicudeschidereininteriorelectromagnetulsemonteazadeasuprausiiininteriorfolosindsuportullcontr','Buc',2.000,1,NULL),
(5,1,5,'Echipamente','5','BUTON','Buton de iesire din plastic folosit in instalatii de control acces. Include baza.','butondeiesiredinplasticfolositininstalatiidecontrolaccesincludebaza','Buc',2.000,1,NULL),
(6,1,6,'Echipamente','6','BUTON','Buton de urgenta verde cu geam din sticla','butondeurgentaverdecugeamdinsticla','Buc',2.000,1,NULL),
(7,1,7,'Echipamente','7','CABLURI','Cablu FTP cat5E, LSZH, 4x2x0,49mm, 100% cupru solid, ecran general cu folie AL, manta exterioara LSZH, culoare albastru, clasa de reactie la foc conform EN50575-2014 : Eca, diametru exterior 6,0mm, cutii unreel de 305m, CE, RoHS, cod EAN 5949022105520, FLUKE PASS','cabluftpcat5elszh4x2x049mm100cuprusolidecrangeneralcufoliealmantaexterioaralszhculoarealbastruclasadereactielafocconformen505752014ecadiametruexterior60mmcutiiunreelde305mcerohscodean5949022','Metru',150.000,0,NULL),
(8,1,8,'Echipamente','8','CANAL CABLU','Canal Cablu cu Banda Adeziva 20x10mm','canalcablucubandaadeziva20x10mm','Buc',20.000,1,NULL),
(9,1,9,'Echipamente','9','CANAL CABLU','Tag de proximitate MIFARE (13.56MHz)\nDimensiuni: 34x28x7 mm\nCuloare: gri sau albastru','tagdeproximitatemifare1356mhzdimensiuni34x28x7mmculoaregrisaualbastru','Buc',15.000,1,NULL),
(10,1,10,'Echipamente','10','DIVERSE','Material marunt de instalare','materialmaruntdeinstalare','Buc',1.000,1,NULL),
(17,3,1,'Echipamente','1','NVR','NVR 8 canale max. 4MP, 8 porturi PoE, SSD 1 TB - HIKVISION , posibilitate de alimentare PoE maxim 58W, rezolutie de pana la 4 MP. Dimensiunile reduse si consumul mic sunt datorate hard-ului SSD de 1 TB preinstalat. Vizualizare live a doua canale de 4 MP sau 4 canale de 1080P. Comprimarea imaginilor H.265+ asigura o economie a spatiului de stocare de pana la 75%. Posibilitatea de conectare cu ajutorul Hik-Connect pentru a facilita managementul retelei.','nvr8canalemax4mp8porturipoessd1tbhikvisionposibilitatedealimentarepoemaxim58wrezolutiedepanala4mpdimensiunileredusesiconsumulmicsuntdatorateharduluissdde1tbpreinstalatvizualizareliveadouacan','Buc',1.000,1,NULL),
(18,3,2,'Echipamente','2','CAMERE IP','Camera de supraveghere video IP, tip Dome de la Hikvision, rezolutie 4MP (2560×1440)@20fps, compresie H.265+/H.265/H.264+/H.264, lentila 2.8mm, unghi vizualizare 99°, EXIR 2.0 si distanta IR max. 30m, detectie miscare si clasificare tinta om/vehicul, posibilitate alimentare PoE, IP67, IK10.','cameradesupravegherevideoiptipdomedelahikvisionrezolutie4mp2560144020fpscompresieh265h265h264h264lentila28mmunghivizualizare99exir20sidistantairmax30mdetectiemiscaresiclasificaretintaomvehic','Buc',2.000,1,NULL),
(19,3,3,'Echipamente','3','RACK','Dulap rack perete 4U 19\'\' 600x450, capacitate incarcare 80 Kg, negru','dulaprackperete4u19600x450capacitateincarcare80kgnegru','Buc',1.000,1,NULL),
(20,3,4,'Echipamente','4','UPS','Sursa de alimentare neintreruptibila DS-UPS600 de la Hikvision are urmatoarele caracteristici:\nAVR incorporat\nIncarcare ultra rapida\nInterval extins al tensiunii de intrare;\nProtectie la suprasarcina;\nProtectie la scurtcircuit;\nProtectie la supratensiune.','sursadealimentareneintreruptibiladsups600delahikvisionareurmatoarelecaracteristiciavrincorporatincarcareultrarapidaintervalextinsaltensiuniideintrareprotectielasuprasarcinaprotectielascurtci','Buc',1.000,1,NULL),
(21,3,5,'Echipamente','5','CABLURI','Cablu FTP cat5E, LSZH, 4x2x0,49mm, 100% cupru solid, ecran general cu folie AL, manta exterioara LSZH, culoare albastru, clasa de reactie la foc conform EN50575-2014 : Eca, diametru exterior 6,0mm, cutii unreel de 305m, CE, RoHS, cod EAN 5949022105520, FLUKE PASS','cabluftpcat5elszh4x2x049mm100cuprusolidecrangeneralcufoliealmantaexterioaralszhculoarealbastruclasadereactielafocconformen505752014ecadiametruexterior60mmcutiiunreelde305mcerohscodean5949022','Metru',30.000,0,NULL),
(22,3,6,'Echipamente','6','CANAL CABLU','Canal Cablu cu Banda Adeziva 20x10mm','canalcablucubandaadeziva20x10mm','Buc',15.000,1,NULL),
(23,4,1,'Echipamente','1','SWITCH','Switch 24 x RJ45 1G PoE, 2 x RJ45 1G, 2 x SFP 1G, Managed - TP-Link\nCompatibilitate cu dispozitive 802.3af/at\nManagement Inteligent: Protejeaza switch-ul impotriva supraincarcarii\nPoE Auto Recovery permite refacerea automata a sistemului pentru a garanta functionarea stabila a dispozitivelor conectate prin PoE.\nPrioritate Port: Asigura calitatea aplicatiilor sensibile','switch24xrj451gpoe2xrj451g2xsfp1gmanagedtplinkcompatibilitatecudispozitive8023afatmanagementinteligentprotejeazaswitchulimpotrivasupraincarcariipoeautorecoverypermiterefacereaautomataasistem','Buc',1.000,1,NULL),
(24,4,2,'Echipamente','2','SWITCH','Switch Easy Smart, 4 x RJ45 1G PoE, 4 x RJ45 1G, Managed - TP-Link\n\nSwitch PoE de la TP-Link avand urmatoarele caracteristici cheie:\n8 porturi RJ45 Gigabit, dintre care 4 porturi PoE+\nOfera monitorizare a retelei, prioritizare a traficului, functii VLAN si PoE Auto Recovery\nInstalare simpla si conectivitate plug & play\nInterfata web pentru utilizatori si Easy Smart Configuration Utility simplifica procesul de configurare\nDesignul fara ventilatoare reduce consumul de energie si elimina zgomotul de operare.','switcheasysmart4xrj451gpoe4xrj451gmanagedtplinkswitchpoedelatplinkavandurmatoarelecaracteristicicheie8porturirj45gigabitdintrecare4porturipoeoferamonitorizareareteleiprioritizareatraficuluif','Buc',11.000,1,NULL),
(25,4,3,'Echipamente','3','RACK','Cabinet metalic neasamblat cu montare pe perete ce permite instalarea echipamentelor standard 19\" dar si a celor pentru CCTV, CATV prin utilizarea de rafturi aditionale.\nusa din sticla securizata, prevazuta cu incuietoare metalica\nconfectionat din tabla de otel laminat la rece, fosfatata, vopsita in camp electrostatic\nmontanti fata-spate numerotati, pentru echipamente si accesorii de 19 inch\npanouri laterale detasabile\ncontine toate accesoriile necesare asamblarii complete\ncapacitate de incarcare marita\npredecupare pentru cabluri si ventilatoare (neincluse)','cabinetmetalicneasamblatcumontarepeperetecepermiteinstalareaechipamentelorstandard19darsiacelorpentrucctvcatvprinutilizareaderafturiaditionaleusadinsticlasecurizataprevazutacuincuietoaremeta','Buc',1.000,1,NULL),
(26,4,4,'Echipamente','4','DIVERSE','Accesorii montaj','accesoriimontaj','Buc',1.000,1,NULL);
